function showContributionForm(pid,id){const c=id?(state.data.contributions||[]).find(x=>x.id===id):null;openModal(`<h2>${c?'تعديل مساهمة':'إضافة مساهمة / خصم'}</h2><div class="form-grid"><div class="field"><label>المبلغ</label><input id="conAmount" type="number" min="0" step="0.01" value="${c?.amount??''}"></div><div class="field"><label>التاريخ</label><input id="conDate" type="date" value="${c?.date||dateNow()}"></div><div class="field full"><label>البيان</label><input id="conDesc" value="${safe(c?.description||'')}" placeholder="مثال: مساهمة سولار"></div></div><div class="actions"><button class="btn primary" id="saveCon">حفظ</button><button class="btn ghost" id="cancelCon">إلغاء</button></div>`);$('#cancelCon').onclick=closeModal;$('#saveCon').onclick=async()=>{const amount=num($('#conAmount').value);if(amount<=0){toast('اكتب مبلغ المساهمة','error');return;}const data={periodId:pid,amount,date:$('#conDate').value,description:$('#conDesc').value.trim()||'مساهمة / خصم',updatedAt:serverTimestamp(),updatedBy:state.user.uid};if(c)await updateDoc(orgDoc('contributions',id),data);else{const r=doc(orgCollection('contributions'));await setDoc(r,{...data,createdAt:serverTimestamp(),createdBy:state.user.uid});}state.loaded=false;await loadData(true);closeModal();toast('تم حفظ المساهمة');if((state.data.periods||[]).find(x=>x.id===pid)?.status==='Calculated')await calculateWeek(pid);else renderContributions();};}

function renderSubscribers(){setTitle('السكان والوحدات','حدد البنايات والوحدات، ثم أضف السكان. بدون حقول حارس أو غاطس هنا.');const rows=(state.data.subscribers||[]).filter(s=>s.active!==false).sort((a,b)=>String(a.code).localeCompare(String(b.code),undefined,{numeric:true})),buildings=state.data.buildings||[],units=state.data.units||[];$('#app').innerHTML=`<section class="grid-2"><div class="panel"><div class="panel-head"><div><h2>البنايات والوحدات</h2><p>البناية والوحدات في نفس المكان لتسهيل الإدارة.</p></div><button class="btn primary" id="addBuilding">+ بناية</button></div><div class="building-grid">${buildings.map(b=>`<div class="building-card"><div><b>${safe(b.name)}</b><span>الكود ${safe(b.code)} • ${units.filter(u=>u.buildingId===b.id).length} وحدات</span></div><div><button class="mini" data-edit-building="${b.id}">تعديل</button><button class="mini red" data-del-building="${b.id}">حذف</button></div></div>`).join('')}</div><div class="table-wrap" style="margin-top:12px"><table class="table"><thead><tr><th>الوحدة</th><th>البناية</th><th>الدور</th><th></th></tr></thead><tbody>${units.map(u=>`<tr><td>${safe(u.code)}</td><td>${safe(buildingName(u.buildingId))}</td><td>${safe(u.floor||'—')}</td><td><button class="mini" data-edit-unit="${u.id}">تعديل</button><button class="mini red" data-del-unit="${u.id}">حذف</button></td></tr>`).join('')||`<tr><td colspan="4">${empty('لا توجد وحدات','')}</td></tr>`}</tbody></table></div><div class="actions"><button class="btn soft" id="addUnit">+ إضافة وحدة</button></div></div><div class="panel"><div class="panel-head"><div><h2>السكان</h2><p>الإضافة والتعديل للمدير/المحاسب فقط. «المديونية» هي المتبقي.</p></div><div class="panel-actions"><button class="btn ghost" id="sortCodeUp">الكود ↑</button><button class="btn ghost" id="sortCodeDown">الكود ↓</button><button class="btn ghost" id="sortNameUp">الاسم ↑</button><button class="btn ghost" id="exportSubs">↓ Excel</button><button class="btn primary" id="addSub">+ ساكن</button></div></div><div class="toolbar"><input id="subSearch" class="search" placeholder="ابحث بالاسم أو الكود…"></div><div class="table-wrap"><table class="table"><thead><tr><th>الكود</th><th>الاسم</th><th>النوع</th><th>البناية</th><th>الوحدة</th><th>المديونية</th><th></th></tr></thead><tbody id="subBody">${subscriberRowsV23(rows)}</tbody></table></div></div></section>`;$('#addBuilding').onclick=()=>showBuildingForm();$('#addUnit').onclick=()=>showUnitForm();$('#addSub').onclick=()=>showSubscriberForm();$('#exportSubs').onclick=exportSubscribersV23;$$('[data-edit-building]').forEach(b=>b.onclick=()=>showBuildingForm(b.dataset.editBuilding));$$('[data-del-building]').forEach(b=>b.onclick=()=>deleteBuilding(b.dataset.delBuilding));$$('[data-edit-unit]').forEach(b=>b.onclick=()=>showUnitForm(b.dataset.editUnit));$$('[data-del-unit]').forEach(b=>b.onclick=()=>deleteUnit(b.dataset.delUnit));let current=rows;const redraw=()=>$('#subBody').innerHTML=subscriberRowsV23(current);$('#subSearch').oninput=e=>{const q=e.target.value.trim();current=rows.filter(s=>[s.name,s.code,s.phone].some(v=>String(v||'').includes(q)));redraw();};$('#sortCodeUp').onclick=()=>{current=[...current].sort((a,b)=>String(a.code).localeCompare(String(b.code),undefined,{numeric:true}));redraw();};$('#sortCodeDown').onclick=()=>{current=[...current].sort((a,b)=>String(b.code).localeCompare(String(a.code),undefined,{numeric:true}));redraw();};$('#sortNameUp').onclick=()=>{current=[...current].sort((a,b)=>String(a.name).localeCompare(String(b.name),'ar'));redraw();};}
function subscriberRowsV23(rows){if(!rows.length)return `<tr><td colspan="7">${empty('لا يوجد سكان','')}</td></tr>`;return rows.map(s=>{const r=subscriberRow(s);return `<tr><td><span class="code">${safe(s.code)}</span></td><td><button class="link" data-account="${s.id}">${safe(s.name)}</button></td><td>${s.type==='خارجي'?'<span class="badge warn">خارجي</span>':'داخلي'}</td><td>${safe(r.buildingName)}</td><td>${safe(r.unitCode)}</td><td class="strong">${money2(r.debt)}</td><td><button class="mini" data-edit-sub="${s.id}">تعديل</button><button class="mini red" data-del-sub="${s.id}">حذف</button></td></tr>`}).join('');}
function showBuildingForm(id){if(!can('admin','manager','accountant')){toast('الإدارة فقط','error');return;}const b=id?(state.data.buildings||[]).find(x=>x.id===id):null;openModal(`<h2>${b?'تعديل البناية':'إضافة بناية'}</h2><div class="form-grid"><div class="field"><label>اسم البناية</label><input id="bName" value="${safe(b?.name||'')}"></div><div class="field"><label>الكود</label><input id="bCode" value="${safe(b?.code||'')}"></div></div><div class="actions"><button class="btn primary" id="saveBuilding">حفظ</button><button class="btn ghost" id="cancelBuilding">إلغاء</button></div>`);$('#cancelBuilding').onclick=closeModal;$('#saveBuilding').onclick=async()=>{const name=$('#bName').value.trim(),code=$('#bCode').value.trim();if(!name||!code){toast('أكمل البيانات','error');return;}if(b)await updateDoc(orgDoc('buildings',id),{name,code,updatedAt:serverTimestamp(),updatedBy:state.user.uid});else{const r=doc(orgCollection('buildings'));await setDoc(r,{name,code,active:true,createdAt:serverTimestamp(),createdBy:state.user.uid});}state.loaded=false;await loadData(true);closeModal();renderSubscribers();};}
function deleteUnit(id){if(!can('admin','manager')){toast('حذف الوحدات للإدارة فقط','error');return;}const u=(state.data.units||[]).find(x=>x.id===id);if(!u)return;if((state.data.subscribers||[]).some(s=>s.unitId===id&&s.active!==false)){toast('لا يمكن حذف وحدة مرتبطة بساكن.','error');return;}if(!confirm(`حذف الوحدة ${u.code}؟`))return;deleteDoc(orgDoc('units',id)).then(()=>{removeLocal('units',id);toast('تم حذف الوحدة');renderSubscribers();});}
function showUnitForm(id){if(!can('admin','manager','accountant')){toast('الإدارة فقط','error');return;}const u=id?(state.data.units||[]).find(x=>x.id===id):null;openModal(`<h2>${u?'تعديل الوحدة':'إضافة وحدة'}</h2><div class="form-grid"><div class="field"><label>البناية</label><select id="uBuilding">${(state.data.buildings||[]).map(b=>`<option value="${b.id}" ${b.id===u?.buildingId?'selected':''}>${safe(b.name)}</option>`).join('')}</select></div><div class="field"><label>رقم الوحدة</label><input id="uCode" value="${safe(u?.code||'')}"></div><div class="field"><label>الدور</label><input id="uFloor" value="${safe(u?.floor||'')}"></div></div><div class="actions"><button class="btn primary" id="saveUnit">حفظ</button><button class="btn ghost" id="cancelUnit">إلغاء</button></div>`);$('#cancelUnit').onclick=closeModal;$('#saveUnit').onclick=async()=>{const buildingId=$('#uBuilding').value,code=$('#uCode').value.trim();if(!buildingId||!code){toast('أكمل البيانات','error');return;}const data={buildingId,code,unitNumber:code,floor:$('#uFloor').value.trim(),active:true,updatedAt:serverTimestamp(),updatedBy:state.user.uid};if(u)await updateDoc(orgDoc('units',id),data);else{const r=doc(orgCollection('units'));await setDoc(r,{...data,createdAt:serverTimestamp(),createdBy:state.user.uid});}state.loaded=false;await loadData(true);closeModal();renderSubscribers();};}
function showSubscriberForm(id){if(!can('admin','manager','accountant')){toast('تعديل بيانات السكان مخصص للإدارة','error');return;}const s=id?(state.data.subscribers||[]).find(x=>x.id===id):null,u=s?unitForSub(s):null;openModal(`<h2>${s?'تعديل بيانات الساكن':'إضافة ساكن جديد'}</h2><p class="modal-lead">هنا فقط بيانات الساكن الأساسية. الحارس والخدمات تُدار من صفحاتها.</p><div class="form-grid"><div class="field"><label>الاسم</label><input id="fName" value="${safe(s?.name||'')}"></div><div class="field"><label>الكود</label><input id="fCode" value="${safe(s?.code||'')}"></div><div class="field"><label>نوع الساكن</label><select id="fType"><option value="داخلي" ${s?.type!=='خارجي'?'selected':''}>داخلي</option><option value="خارجي" ${s?.type==='خارجي'?'selected':''}>مستهلك خارجي</option></select></div><div class="field"><label>الهاتف</label><input id="fPhone" value="${safe(s?.phone||'')}"></div><div class="field"><label>البناية</label><select id="fBuilding"><option value="">${s?.type==='خارجي'?'خارجي — بدون بناية':'اختر البناية'}</option>${(state.data.buildings||[]).map(b=>`<option value="${b.id}" ${b.id===u?.buildingId?'selected':''}>${safe(b.name)}</option>`).join('')}</select></div><div class="field"><label>الوحدة</label><select id="fUnit"><option value="">${s?.type==='خارجي'?'بدون وحدة':'اختر الوحدة'}</option>${(state.data.units||[]).map(x=>`<option value="${x.id}" ${x.id===u?.id?'selected':''}>${safe(buildingName(x.buildingId))} — ${safe(x.code)}</option>`).join('')}</select></div><div class="field full"><label>ملاحظات</label><textarea id="fNotes">${safe(s?.notes||'')}</textarea></div></div><div class="actions"><button class="btn primary" id="saveSub">حفظ</button><button class="btn ghost" id="cancelSub">إلغاء</button></div>`);$('#cancelSub').onclick=closeModal;$('#saveSub').onclick=async()=>{const name=$('#fName').value.trim(),code=$('#fCode').value.trim(),type=$('#fType').value;if(!name||!code){toast('اكتب الاسم والكود','error');return;}if((state.data.subscribers||[]).some(x=>x.code===code&&x.id!==id)){toast('الكود مستخدم بالفعل','error');return;}const unitId=type==='خارجي'?null:($('#fUnit').value||null);const data={name,code,type,phone:$('#fPhone').value.trim(),unitId,notes:$('#fNotes').value.trim(),active:true};if(s)await updateDoc(orgDoc('subscribers',id),{...data,updatedAt:serverTimestamp(),updatedBy:state.user.uid});else{const sr=doc(orgCollection('subscribers'));await setDoc(sr,{...data,createdAt:serverTimestamp(),createdBy:state.user.uid});const mr=doc(orgCollection('meters'));await setDoc(mr,{meterCode:`W-${code}`,meterType:'مياه',subscriberId:sr.id,unitId,active:true,createdAt:serverTimestamp(),createdBy:state.user.uid});}state.loaded=false;await loadData(true);closeModal();toast('تم الحفظ');renderSubscribers();};}

function renderPayments(){setTitle('الدفعات','الدفعة تُسجل في أسبوعها فقط، وأثرها ينتقل عبر المديونية/الرصيد الدائن.');const rows=[...(state.data.payments||[])].sort((a,b)=>String(b.paymentDate||'').localeCompare(String(a.paymentDate||''))),subs=(state.data.subscribers||[]);$('#app').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>الدفعات المسجلة</h2><p>الدفعة لا تتكرر في الأسبوع التالي. المتبقي أو الزيادة فقط يترحل.</p></div><div class="panel-actions"><button class="btn ghost" id="exportPays">↓ Excel</button><button class="btn primary" id="newPay">+ تسجيل دفعة</button></div></div><div class="table-wrap"><table class="table"><thead><tr><th>التاريخ</th><th>الأسبوع</th><th>الساكن</th><th>المبلغ</th><th>الطريقة</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td>${fmtDate(p.paymentDate)}</td><td>${safe(periodById(p.periodId)?.label||'—')}</td><td>${safe(subs.find(s=>s.id===p.subscriberId)?.name||'—')}</td><td>${money2(p.amount)}</td><td>${safe(p.method||'—')}</td><td><button class="mini red" data-del-payment="${p.id}">حذف</button></td></tr>`).join('')||`<tr><td colspan="6">${empty('لا توجد دفعات','')}</td></tr>`}</tbody></table></div></section>`;$('#newPay').onclick=showPaymentForm;$('#exportPays').onclick=exportPaymentsV23;$$('[data-del-payment]').forEach(b=>b.onclick=()=>deletePayment(b.dataset.delPayment));}
function showPaymentForm(){const ps=latestPeriods(),subs=(state.data.subscribers||[]).filter(s=>s.active!==false);openModal(`<h2>تسجيل دفعة</h2><div class="form-grid"><div class="field full"><label>الساكن</label><select id="paySub">${subs.map(s=>`<option value="${s.id}">${safe(s.code)} — ${safe(s.name)}</option>`).join('')}</select></div><div class="field"><label>الأسبوع</label><select id="payPeriod">${ps.map(p=>`<option value="${p.id}" ${p.id===selectedPeriod()?.id?'selected':''}>${safe(p.label)}</option>`).join('')}</select></div><div class="field"><label>المبلغ</label><input id="payAmount" type="number" min="0" step="0.01"></div><div class="field"><label>التاريخ</label><input id="payDate" type="date" value="${dateNow()}"></div><div class="field"><label>طريقة الدفع</label><select id="payMethod"><option>نقدي</option><option>تحويل بنكي</option><option>أخرى</option></select></div><div class="field"><label>رقم الإيصال</label><input id="payReceipt"></div><div class="field full"><label>ملاحظة</label><textarea id="payNote"></textarea></div></div><div class="actions"><button class="btn primary" id="savePay">حفظ الدفعة</button><button class="btn ghost" id="cancelPay">إلغاء</button></div>`);$('#cancelPay').onclick=closeModal;$('#savePay').onclick=async()=>{const subscriberId=$('#paySub').value,periodId=$('#payPeriod').value,amount=num($('#payAmount').value);if(!subscriberId||!periodId||amount<=0){toast('أكمل بيانات الدفعة','error');return;}const ref=doc(orgCollection('payments')),lr=doc(orgCollection('ledger'));const payment={subscriberId,periodId,amount,paymentDate:$('#payDate').value,method:$('#payMethod').value,receiptNumber:$('#payReceipt').value.trim(),note:$('#payNote').value.trim(),createdBy:state.user.uid,createdAt:serverTimestamp()};const batch=writeBatch(db);batch.set(ref,payment);batch.set(lr,{subscriberId,periodId,transactionType:'PAYMENT',credit:amount,debit:0,description:'دفعة',referenceId:ref.id,paymentDate:payment.paymentDate,createdAt:serverTimestamp(),createdBy:state.user.uid});await batch.commit();state.loaded=false;await loadData(true);closeModal();toast('تم تسجيل الدفعة');renderPayments();};}

function renderDebts(){setTitle('الديون السابقة','هنا تسجل فقط الديون الحقيقية القديمة أو المبالغ غير المسددة التي تريد بدء البرنامج بها.');const rows=[...(state.data.debts||[])].sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));const subs=(state.data.subscribers||[]);$('#app').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>الديون السابقة</h2><p>لا تحتاج تنزيل جداول الأسابيع القديمة؛ سجل الدين المتبقي كرقم واحد.</p></div><button class="btn primary" id="addDebt">+ إضافة دين</button></div><div class="table-wrap"><table class="table"><thead><tr><th>التاريخ</th><th>الساكن</th><th>البيان</th><th>المبلغ</th><th></th></tr></thead><tbody>${rows.map(d=>`<tr><td>${fmtDate(d.date)}</td><td>${safe(subs.find(s=>s.id===d.subscriberId)?.name||'—')}</td><td>${safe(d.description||'دين سابق')}</td><td>${money2(d.amount)}</td><td><button class="mini red" data-del-debt="${d.id}">حذف</button></td></tr>`).join('')||`<tr><td colspan="5">${empty('لا توجد ديون','')}</td></tr>`}</tbody></table></div></section>`;$('#addDebt').onclick=showDebtForm;$$('[data-del-debt]').forEach(b=>b.onclick=()=>deleteDebt(b.dataset.delDebt));}
function showDebtForm(){const subs=(state.data.subscribers||[]).filter(s=>s.active!==false);openModal(`<h2>إضافة دين سابق</h2><div class="form-grid"><div class="field full"><label>الساكن</label><select id="dSub">${subs.map(s=>`<option value="${s.id}">${safe(s.code)} — ${safe(s.name)}</option>`).join('')}</select></div><div class="field"><label>المبلغ</label><input id="dAmount" type="number" min="0" step="0.01"></div><div class="field"><label>التاريخ</label><input id="dDate" type="date" value="${dateNow()}"></div><div class="field full"><label>البيان</label><input id="dDesc" placeholder="مثال: متأخرات قبل بدء البرنامج"></div></div><div class="actions"><button class="btn primary" id="saveDebt">حفظ الدين</button><button class="btn ghost" id="cancelDebt">إلغاء</button></div>`);$('#cancelDebt').onclick=closeModal;$('#saveDebt').onclick=async()=>{const subscriberId=$('#dSub').value,amount=num($('#dAmount').value);if(!subscriberId||amount<=0){toast('أكمل البيانات','error');return;}const ref=doc(orgCollection('debts')),lr=doc(orgCollection('ledger'));const data={subscriberId,amount,paidAmount:0,date:$('#dDate').value,description:$('#dDesc').value.trim()||'دين سابق',createdAt:serverTimestamp(),createdBy:state.user.uid};const batch=writeBatch(db);batch.set(ref,data);batch.set(lr,{subscriberId,transactionType:'DEBT',debit:amount,credit:0,description:data.description,referenceId:ref.id,date:data.date,createdAt:serverTimestamp(),createdBy:state.user.uid});await batch.commit();state.loaded=false;await loadData(true);closeModal();toast('تم تسجيل الدين');renderDebts();};}

function renderReports(){setTitle('التقارير وكشوف الحساب','اختر الساكن والأسبوع. ثم خذ الرسالة أو الكشف الكامل للملف.');const subs=(state.data.subscribers||[]).filter(s=>s.active!==false).sort((a,b)=>String(a.code).localeCompare(String(b.code),undefined,{numeric:true})),ps=latestPeriods();$('#app').innerHTML=`<section class="report-hero"><div><span class="guide-badge">كشف حساب</span><h2>كشف حساب ساكن</h2><p>اختر شخصًا + أسبوعًا. الكشف نفسه هو مصدر الرسالة.</p></div><div class="report-mark">₪</div></section><section class="report-card report-card-wide"><div class="form-grid"><div class="field"><label>الساكن</label><select id="reportSub"><option value="">اختر الساكن</option>${subs.map(s=>`<option value="${s.id}">${safe(s.code)} — ${safe(s.name)}</option>`).join('')}</select></div><div class="field"><label>الأسبوع</label><select id="reportPeriod"><option value="">اختر الأسبوع</option>${ps.map(p=>`<option value="${p.id}">${safe(p.label)} — ${fmtDate(p.startDate)}</option>`).join('')}</select></div><div class="field"><label>من أسبوع (لـPDF)</label><select id="pdfFrom"><option value="">أقدم متاح</option>${ps.map(p=>`<option value="${p.id}">${safe(p.label)}</option>`).join('')}</select></div><div class="field"><label>إلى أسبوع (لـPDF)</label><select id="pdfTo"><option value="">أحدث متاح</option>${ps.map(p=>`<option value="${p.id}">${safe(p.label)}</option>`).join('')}</select></div></div><div class="actions"><button class="btn primary" id="showReport">عرض الكشف</button><button class="btn gold" id="downloadPdf">↓ تنزيل كشف PDF</button><button class="btn ghost" id="exportSelectedWeek">↓ Excel للأسبوع</button></div></section><section id="resident-report-holder"></section>`;$('#showReport').onclick=()=>{const id=$('#reportSub').value,pid=$('#reportPeriod').value;if(!id||!pid){toast('اختر الساكن والأسبوع','error');return;}renderResidentReportCardV23(id,pid);};$('#downloadPdf').onclick=()=>{const id=$('#reportSub').value;if(!id){toast('اختر الساكن أولًا','error');return;}downloadResidentPdfV23(id,$('#pdfFrom').value,$('#pdfTo').value);};$('#exportSelectedWeek').onclick=()=>{const pid=$('#reportPeriod').value;if(!pid){toast('اختر الأسبوع أولًا','error');return;}exportWeekV23(pid);};}
function renderResidentReportCardV23(id,pid){const sum=residentWeekSummary(id,pid),holder=$('#resident-report-holder');if(!sum||!holder)return;const weeks=residentAllWeeks(id),text=messageForResident(sum);holder.innerHTML=`<section class="resident-report-card" id="residentReportCard"><div class="resident-report-head"><div><span class="code">${safe(sum.s.code)}</span><h2>${safe(sum.s.name)}</h2><p>${safe(subscriberRow(sum.s).buildingName)} · ${safe(subscriberRow(sum.s).unitCode)}</p></div><div class="balance-box"><span>المديونية بعد هذا الأسبوع</span><b>${money2(Math.max(0,sum.required))}</b></div></div><div class="resident-message"><div class="message-head"><div><h3>الرسالة الجاهزة</h3><p>نفس أرقام كشف الحساب.</p></div><button class="btn primary" id="copyMsg">نسخ النص</button></div><textarea id="msgText" readonly>${safe(text)}</textarea></div><div class="account-section"><div class="panel-head"><div><h3>كشف حساب شامل</h3><p>كل أسبوع في صف واحد. لا يوجد جدول حركات إضافي.</p></div></div><div class="table-wrap"><table class="table report-wide"><thead><tr><th>الأسبوع</th><th>السحب</th><th>المياه</th><th>الحارس</th><th>مصاريف أخرى</th><th>ديون سابقة</th><th>قبل الدفعات</th><th>الدفعات</th><th>المطلوب</th></tr></thead><tbody>${weeks.map(w=>`<tr><td>${safe(w.p.label)}<small>${fmtDate(w.p.startDate)} إلى ${fmtDate(w.p.endDate)}</small></td><td>${fmt(w.consumption,3)} كوب</td><td>${money2(w.waterCharge)}</td><td>${money2(w.guard)}</td><td>${money2(w.other)}</td><td>${money2(w.previousDebt)}</td><td>${money2(w.beforePayments)}</td><td>${money2(w.payments)}</td><td class="strong">${money2(w.required)}</td></tr>`).join('')}</tbody></table></div></div></section>`;$('#copyMsg').onclick=async()=>{try{await navigator.clipboard.writeText(text);toast('تم نسخ الرسالة');}catch{const t=$('#msgText');t.select();document.execCommand('copy');toast('تم النسخ');}};}

async function downloadResidentPdfV23(id,fromId,toId){const all=residentAllWeeks(id);if(!all.length){toast('لا يوجد كشف لهذا الساكن','error');return;}let weeks=all;const ps=latestPeriods().sort((a,b)=>String(a.startDate).localeCompare(String(b.startDate)));if(fromId)weeks=weeks.filter(w=>String(w.p.startDate)>=String(periodById(fromId)?.startDate||''));if(toId)weeks=weeks.filter(w=>String(w.p.startDate)<=String(periodById(toId)?.startDate||''));if(!weeks.length){toast('لا توجد أسابيع ضمن الاختيار','error');return;}if(!window.html2canvas||!window.jspdf?.jsPDF){toast('مكتبات PDF لم تُحمّل بعد، أعد المحاولة','error');return;}const s=(state.data.subscribers||[]).find(x=>x.id===id);const box=document.createElement('div');box.style.cssText='position:fixed;left:-10000px;top:0;width:1200px;background:#fff;padding:40px;direction:rtl;font-family:Cairo,Arial,sans-serif;color:#143d38;';box.innerHTML=`<div style="font-size:28px;font-weight:800;margin-bottom:8px">كشف حساب — ${safe(s?.name||'')}</div><div style="margin-bottom:18px">عمارة الأمين • ${safe(subscriberRow(s).buildingName)} • ${safe(subscriberRow(s).unitCode)}</div><table style="width:100%;border-collapse:collapse;font-size:16px"><thead><tr>${['الأسبوع','السحب','المياه','الحارس','مصاريف أخرى','ديون سابقة','قبل الدفعات','الدفعات','المطلوب'].map(h=>`<th style="border:1px solid #ccd9d7;padding:10px;background:#edf5f3">${h}</th>`).join('')}</tr></thead><tbody>${weeks.map(w=>`<tr>${[`<b>${safe(w.p.label)}</b><br><small>${fmtDate(w.p.startDate)} - ${fmtDate(w.p.endDate)}</small>`,`${fmt(w.consumption,3)} كوب`,money2(w.waterCharge),money2(w.guard),money2(w.other),money2(w.previousDebt),money2(w.beforePayments),money2(w.payments),money2(w.required)].map(v=>`<td style="border:1px solid #ccd9d7;padding:9px;text-align:center">${v}</td>`).join('')}</tr>`).join('')}</tbody></table>`;document.body.appendChild(box);const canvas=await html2canvas(box,{scale:2,backgroundColor:'#fff',useCORS:true});document.body.removeChild(box);const {jsPDF}=window.jspdf;const pdf=new jsPDF({orientation:'landscape',unit:'mm',format:'a4'});const margin=8;const pageW=297-margin*2,pageH=210-margin*2;const imgW=pageW,imgH=canvas.height*imgW/canvas.width;let y=margin,remaining=imgH,sourceY=0;while(remaining>0){const sliceH=Math.min(pageH,remaining);const sliceCanvas=document.createElement('canvas');sliceCanvas.width=canvas.width;sliceCanvas.height=Math.floor(canvas.height*(sliceH/imgH));const ctx=sliceCanvas.getContext('2d');ctx.drawImage(canvas,0,sourceY,canvas.width,sliceCanvas.height,0,0,sliceCanvas.width,sliceCanvas.height);if(y>margin)pdf.addPage();pdf.addImage(sliceCanvas.toDataURL('image/png'),'PNG',margin,margin,imgW,sliceH);remaining-=sliceH;sourceY+=sliceCanvas.height;}pdf.save(`كشف_حساب_${String(s?.code||id)}.pdf`);toast('تم تنزيل كشف PDF');}

function renderSettings(){setTitle('الإعدادات والصلاحيات','الحذف والإدارة المتقدمة للبيانات.');const ps=latestPeriods();$('#app').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>الحساب</h2><p>${safe(state.user?.email||'')} • ${roleName(state.profile.role)}</p></div><button class="btn ghost" id="logoutSet">تسجيل الخروج</button></div></section><section class="panel danger-panel"><div class="panel-head"><div><h2>حذف أسبوع</h2><p>حذف هذا الأسبوع فقط، أو كل الأسابيع ما عدا الأسبوع الذي تختاره.</p></div></div><div class="danger-actions"><select id="deletePeriod"><option value="">اختر أسبوعًا</option>${ps.map(p=>`<option value="${p.id}">${safe(p.label)} — ${fmtDate(p.startDate)}</option>`).join('')}</select><button class="btn danger" id="deletePeriodBtn">حذف هذا الأسبوع فقط</button><button class="btn danger" id="deleteExceptBtn">حذف كل الأسابيع ما عدا هذا</button></div></section><section class="panel"><div class="section-note"><b>تنبيه:</b> حذف البيانات نهائي من Firebase ولا ينعكس على الكود إلا عبر علامة الحذف؛ البيانات المضمنة نفسها في هذا الإصدار هي 03/09/2026 فقط.</div></section>`;$('#logoutSet').onclick=()=>signOut(auth);$('#deletePeriodBtn').onclick=()=>deleteWeek($('#deletePeriod').value);$('#deleteExceptBtn').onclick=()=>deleteAllWeeksExcept($('#deletePeriod').value);}

async function deleteWeek(pid){if(!can('admin')){toast('الحذف للمدير فقط','error');return;}if(!pid){toast('اختر أسبوعًا','error');return;}const p=periodById(pid);if(!confirm(`سيتم حذف ${p?.label||'الأسبوع'} بكل قراءاته ومصاريفه ودفعاته وحساباته المرتبطة.

هل أنت متأكد؟`))return;const batch=writeBatch(db);const collections=['readings','energyReadings','waterSummary','costs','contributions','guardServices','ledger','payments'];for(const c of collections){for(const r of (state.data[c]||[]).filter(x=>x.periodId===pid))batch.delete(orgDoc(c,r.id));}batch.delete(orgDoc('periods',pid));const seeded=INITIAL_DATA.periods.find(x=>x.id===pid);if(seeded)batch.set(orgDoc('seedDeletes',`periods__${pid}`),{key:`periods/${pid}`,deletedAt:serverTimestamp(),deletedBy:state.user.uid});await batch.commit();state.loaded=false;await loadData(true);state.periodId=latestPeriods()[0]?.id||null;toast('تم حذف الأسبوع');renderSettings();}
async function deleteAllWeeksExcept(keepId){if(!can('admin')){toast('الحذف للمدير فقط','error');return;}if(!keepId){toast('اختر أسبوعًا','error');return;}const ids=latestPeriods().filter(p=>p.id!==keepId).map(p=>p.id);if(!ids.length){toast('لا توجد أسابيع أخرى للحذف');return;}if(!confirm(`سيتم حذف ${ids.length} أسبوعًا مع كل بياناتها. سيبقى الأسبوع المختار فقط.

هل أنت متأكد؟`))return;for(const pid of ids)await deleteWeekSilent(pid);state.loaded=false;await loadData(true);state.periodId=keepId;toast('تم حذف كل الأسابيع ما عدا المختار');renderSettings();}
async function deleteWeekSilent(pid){const batch=writeBatch(db);for(const c of ['readings','energyReadings','waterSummary','costs','contributions','guardServices','ledger','payments'])for(const r of (state.data[c]||[]).filter(x=>x.periodId===pid))batch.delete(orgDoc(c,r.id));batch.delete(orgDoc('periods',pid));const seeded=INITIAL_DATA.periods.find(x=>x.id===pid);if(seeded)batch.set(orgDoc('seedDeletes',`periods__${pid}`),{key:`periods/${pid}`,deletedAt:serverTimestamp(),deletedBy:state.user.uid});await batch.commit();state.data.periods=(state.data.periods||[]).filter(p=>p.id!==pid);}

async function deleteReading(id){if(!can('admin','manager','accountant','operator')){toast('لا تملك الصلاحية','error');return;}if(!confirm('حذف هذه القراءة؟'))return;const r=(state.data.readings||[]).find(x=>x.id===id);const batch=writeBatch(db);batch.delete(orgDoc('readings',id));for(const x of (state.data.ledger||[]).filter(x=>x.referenceId===id))batch.delete(orgDoc('ledger',x.id));await batch.commit();removeLocal('readings',id);state.loaded=true;toast('تم حذف القراءة');renderReadings();}
async function deleteEnergyReading(id){if(!can('admin','manager','accountant')){toast('الحذف للإدارة','error');return;}if(!confirm('حذف قراءة الكهرباء؟'))return;await deleteDoc(orgDoc('energyReadings',id));removeLocal('energyReadings',id);toast('تم حذف القراءة');renderEnergy();}
async function deleteCost(id){if(!can('admin','manager','accountant')){toast('الحذف للإدارة','error');return;}if(!confirm('حذف المصروف وحركاته الموزعة؟'))return;const batch=writeBatch(db);batch.delete(orgDoc('costs',id));for(const x of (state.data.ledger||[]).filter(x=>x.referenceId===id))batch.delete(orgDoc('ledger',x.id));await batch.commit();state.loaded=false;await loadData(true);toast('تم حذف المصروف');renderCosts();}
async function deleteContribution(id){if(!can('admin','manager','accountant')){toast('الحذف للإدارة','error');return;}if(!confirm('حذف هذه المساهمة؟'))return;const c=(state.data.contributions||[]).find(x=>x.id===id);const pid=c?.periodId;await deleteDoc(orgDoc('contributions',id));removeLocal('contributions',id);toast('تم حذف المساهمة');renderContributions();if(pid&&periodById(pid)?.status==='Calculated')await calculateWeek(pid);}
async function deleteGuardService(pid){if(!can('admin','manager','accountant'))return;if(!confirm('حذف خدمة الحارس لهذا الأسبوع؟'))return;const svc=guardServiceForPeriod(pid);const batch=writeBatch(db);if(svc)batch.delete(orgDoc('guardServices',svc.id));for(const x of (state.data.ledger||[]).filter(x=>x.periodId===pid&&x.transactionType==='SERVICE'&&x.serviceCode==='GUARD'))batch.delete(orgDoc('ledger',x.id));await batch.commit();state.loaded=false;await loadData(true);toast('تم حذف خدمة الحارس');renderGuard();}
async function deletePayment(id){if(!can('admin','manager','accountant')){toast('الحذف للإدارة','error');return;}if(!confirm('حذف الدفعة نهائيًا؟'))return;const p=(state.data.payments||[]).find(x=>x.id===id);const batch=writeBatch(db);batch.delete(orgDoc('payments',id));for(const x of (state.data.ledger||[]).filter(x=>x.referenceId===id))batch.delete(orgDoc('ledger',x.id));await batch.commit();removeLocal('payments',id);state.data.ledger=(state.data.ledger||[]).filter(x=>x.referenceId!==id);toast('تم حذف الدفعة');renderPayments();}
async function deleteDebt(id){if(!can('admin','manager','accountant'))return;if(!confirm('حذف الدين وحركته المالية؟'))return;const d=(state.data.debts||[]).find(x=>x.id===id);const batch=writeBatch(db);batch.delete(orgDoc('debts',id));for(const x of (state.data.ledger||[]).filter(x=>x.referenceId===id))batch.delete(orgDoc('ledger',x.id));await batch.commit();removeLocal('debts',id);state.data.ledger=(state.data.ledger||[]).filter(x=>x.referenceId!==id);toast('تم حذف الدين');renderDebts();}
async function deleteBuilding(id){if(!can('admin','manager'))return;const units=(state.data.units||[]).filter(u=>u.buildingId===id);if(units.length){toast('لا يمكن حذف بناية فيها وحدات. احذف الوحدات أولًا.','error');return;}if(!confirm('حذف البناية؟'))return;await deleteDoc(orgDoc('buildings',id));removeLocal('buildings',id);toast('تم حذف البناية');renderSubscribers();}
async function deleteSubscriber(id){if(!can('admin','manager')){toast('حذف السكان للمدير فقط','error');return;}const s=(state.data.subscribers||[]).find(x=>x.id===id);if(!s)return;if(!confirm(`سيتم حذف ${s.name} وقراءات ودفعات وديون حركاته المالية. لا يمكن التراجع من داخل الموقع.

متأكد؟`))return;const batch=writeBatch(db);batch.delete(orgDoc('subscribers',id));for(const m of (state.data.meters||[]).filter(x=>x.subscriberId===id))batch.delete(orgDoc('meters',m.id));for(const c of ['readings','payments','debts','ledger'])for(const x of (state.data[c]||[]).filter(r=>r.subscriberId===id))batch.delete(orgDoc(c,x.id));await batch.commit();removeLocal('subscribers',id);toast('تم حذف الساكن بكل بياناته');renderSubscribers();}

function exportXlsxV23(rows,sheet,file){if(window.XLSX){const wb=XLSX.utils.book_new();const ws=XLSX.utils.json_to_sheet(rows);XLSX.utils.book_append_sheet(wb,ws,String(sheet).slice(0,31));XLSX.writeFile(wb,file);toast('تم تنزيل Excel');return;}const head=Object.keys(rows[0]||{});const csv=[head.join(','),...rows.map(r=>head.map(k=>`"${String(r[k]??'').replaceAll('"','""')}"`).join(','))].join('\n');const a=document.createElement('a');a.href='data:text/csv;charset=utf-8,'+encodeURIComponent(csv);a.download=file.replace(/\.xlsx$/i,'.csv');a.click();toast('تم تنزيل ملف يفتح في Excel');}
function exportSubscribersV23(){exportXlsxV23((state.data.subscribers||[]).filter(s=>s.active!==false).map(s=>{const r=subscriberRow(s);return{الكود:s.code,الاسم:s.name,النوع:s.type,البناية:r.buildingName,الوحدة:r.unitCode,المديونية:r.debt};}),'السكان','سكان_عمارة_الأمين.xlsx');}
function exportPaymentsV23(){exportXlsxV23((state.data.payments||[]).map(p=>({التاريخ:p.paymentDate,الأسبوع:periodById(p.periodId)?.label||'',الساكن:(state.data.subscribers||[]).find(s=>s.id===p.subscriberId)?.name||'',المبلغ:p.amount,الطريقة:p.method||'',الإيصال:p.receiptNumber||''})),'الدفعات','دفعات_عمارة_الأمين.xlsx');}
function exportWeekV23(pid){const p=periodById(pid);const rows=readingsForPeriod(pid).map(r=>{const s=subscriberByMeter((state.data.meters||[]).find(m=>m.id===r.meterId));return{الكود:s?.code||'',الاسم:s?.name||'',القراءة_السابقة:r.previousReading??'',القراءة_الحالية:r.currentReading??'',السحب:r.consumption??'',سعر_الكوب:r.unitPrice??p?.waterUnitPrice??'',قيمة_المياه:r.chargeAmount??''};});exportXlsxV23(rows,'قراءات الماء',`قراءات_${pid}.xlsx`);}

function renderHistorical(){setTitle('البيانات التاريخية','بيانات البداية المضمنة في الكود.');const c={};for(const [k,v] of Object.entries(INITIAL_DATA))if(Array.isArray(v))c[k]=v.length;$('#app').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>البيانات المضمنة</h2><p>هذه النسخة تحتوي على 03/09/2026 فقط كبيانات بداية.</p></div></div><div class="stats"><div class="stat"><div class="stat-label">السكان</div><div class="stat-value">${c.subscribers||0}</div></div><div class="stat"><div class="stat-label">الأسبوع</div><div class="stat-value">${c.periods||0}</div></div><div class="stat"><div class="stat-label">قراءات الماء</div><div class="stat-value">${c.readings||0}</div></div><div class="stat"><div class="stat-label">قراءات الكهرباء</div><div class="stat-value">${c.energyReadings||0}</div></div></div></section>`;}
function showGuide(){openModal(`<div class="guide-hero"><span class="guide-badge">شرح عملي</span><h2>كيف تستخدم الموقع كل أسبوع؟</h2><p>1) افتح أسبوعًا من التقويم. 2) أدخل قراءات أبو زايد والـسويسي. 3) أدخل قراءات السكان. 4) أدخل قراءة الخارجي. 5) أضف المصاريف والحارس والمساهمات. 6) اضغط «احسب الآن». 7) من التقارير اختر الساكن والأسبوع وانسخ الرسالة أو نزّل كشف PDF.</p><div class="guide-demo"><div class="demo-row"><span>قراءة حالية</span><b>126500</b></div><div class="demo-row"><span>قراءة سابقة</span><b>125000</b></div><div class="demo-row"><span>السحب</span><b>1.500 كوب</b></div><div class="demo-row"><span>سعر الكوب</span><b>29 ₪</b></div></div><div class="actions"><button class="btn primary" id="guideGoRead">اذهب لقراءات الماء</button><button class="btn ghost" id="guideClose">إغلاق</button></div></div>`);$('#guideClose').onclick=closeModal;$('#guideGoRead').onclick=()=>{closeModal();navigate('readings',selectedPeriod()?.id);};}
function renderPending(){setTitle('بانتظار الموافقة','حسابك يحتاج موافقة المدير.');$('#app').innerHTML=`<section class="panel" style="max-width:680px;margin:50px auto;text-align:center;padding:40px"><div style="font-size:40px">⌛</div><h2>بانتظار موافقة المدير</h2><p>${safe(state.user?.email||'حسابك')}</p></section>`;}

// Global event wiring
document.addEventListener('click',e=>{const v=e.target.closest('[data-view]');if(v)navigate(v.dataset.view);const a=e.target.closest('[data-account]');if(a)openAccountV23(a.dataset.account);const ed=e.target.closest('[data-edit-sub]');if(ed)showSubscriberForm(ed.dataset.editSub);const ds=e.target.closest('[data-del-sub]');if(ds)deleteSubscriber(ds.dataset.delSub);});
function openAccountV23(id){const s=(state.data.subscribers||[]).find(x=>x.id===id);if(!s)return;state.view='reports';setActiveNav();loadData().then(()=>{renderReports();$('#reportSub').value=id;const p=selectedPeriod();if(p){$('#reportPeriod').value=p.id;renderResidentReportCardV23(id,p.id);}});}
$('#googleLogin')?.addEventListener('click',async()=>{try{await signInWithPopup(auth,provider)}catch(e){const b=$('#auth-error');b.textContent=e?.message||'تعذر تسجيل الدخول';b.classList.remove('hidden');}});$('#logoutBtn')?.addEventListener('click',()=>signOut(auth));$('#refreshBtn')?.addEventListener('click',()=>navigate(state.view,state.periodId,true));$('#mobileMenu')?.addEventListener('click',()=>$('#sidebar')?.classList.toggle('open'));$('#quickPaymentBtn')?.addEventListener('click',showPaymentForm);$('#quickPeriod')?.addEventListener('click',showPeriodForm);$('#modalClose')?.addEventListener('click',closeModal);$('#modal')?.addEventListener('click',e=>{if(e.target===e.currentTarget)closeModal();});
onAuthStateChanged(auth,async user=>{state.user=user;$('#boot')?.classList.add('hidden');if(!user){$('#auth-screen')?.classList.remove('hidden');$('#app-shell')?.classList.add('hidden');return;}$('#auth-screen')?.classList.add('hidden');$('#app-shell')?.classList.remove('hidden');$('#userName').textContent=user.displayName||user.email||'المستخدم';$('#userAvatar').textContent=(user.displayName||user.email||'م').slice(0,1);$('#userRole').textContent='جارٍ التحقق…';try{state.profile=await ensureProfile();$('#userRole').textContent=roleName(state.profile.role);if(state.profile.role==='pending'){renderPending();return;}state.loaded=false;await loadData(true);await ensureDefaults();await navigate('dashboard');}catch(e){console.error(e);$('#app').innerHTML=`<section class="panel" style="max-width:820px;margin:40px auto"><h2>تعذر تحميل البيانات</h2><p>${safe(e?.message||'تحقق من إعدادات Firebase وقواعد Firestore.')}</p></section>`;}});
